<?php
declare(strict_types=1);require_once __DIR__.'/history-layout.php';require_once __DIR__.'/stock-outcomes.php';
function stock_is_shortage(array $row):bool {return !empty($row['created'])&&strtoupper(trim((string)($row['status']??'')))==='HH';}
function stock_tracking(string $v):string {return preg_replace('/\D/','',$v);}
function stock_item_map(array $items):array {$map=[];foreach($items as $i){$size=strtr(strtoupper($i['size']),['XXXL'=>'3XL','XXL'=>'2XL']);$key=$i['sku'].'|'.$size;$map[$key]=($map[$key]??0)+(int)$i['qty'];}return $map;}
function stock_group_rows(array $rows):array {$groups=[];foreach($rows as $row){if(!$row['created'])continue;$code=stock_tracking($row['tracking']);$key=$code!==''?$code:$row['sheetId'].'|'.$row['row'];if(!isset($groups[$key])){$groups[$key]=$row;continue;}$group=&$groups[$key];foreach(['items','incoming'] as $field){$map=stock_item_map($group[$field]??[]);foreach(stock_item_map($row[$field]??[]) as $pair=>$qty){if(isset($map[$pair])&&$map[$pair]!==$qty)$group['quantityConflict']=true;$map[$pair]=max($map[$pair]??0,$qty);}$group[$field]=[];foreach($map as $pair=>$qty){[$sku,$size]=explode('|',$pair,2);$group[$field][]=['sku'=>$sku,'size'=>$size,'qty'=>$qty];}}if(trim($group['measurements']??'')==='')$group['measurements']=$row['measurements']??'';if(trim($group['status']??'')==='')$group['status']=$row['status']??'';$group['sizeCharts']=array_replace($row['sizeCharts']??[],$group['sizeCharts']??[]);$group['text']=implode(' + ',array_unique([$group['text'],$row['text']]));unset($group);}return array_values($groups);}
function stock_return_items(array $order,?array $entry,?array $manual):array {
 if(!empty($order['quantityConflict']))return ['items'=>[],'error'=>'Mã vận đơn trùng nhưng số lượng khác giữa các dòng; kiểm tra BẢNG ĐƠN.'];
 $pool=stock_item_map(array_merge($order['items'],$order['incoming']??[]));if($manual!==null){foreach($manual as $key=>$qty)if(!isset($pool[$key])||!is_int($qty)||$qty<0||$qty>$pool[$key])return ['items'=>[],'error'=>'Phân bổ đã lưu vượt số lượng của đơn hiện tại.'];return ['items'=>$manual,'error'=>''];}
 $raw=$entry['raw']??'';$selected=[];$explicit=false;
 preg_match_all('/(?<![\p{L}\d])([A-Z]{1,8}\d{1,6})\s*(?:[\/:,-]\s*)?(?:SIZE\s*)?(4XL|3XL|2XL|XXXL|XXL|XS|XL|S|M|L)(?![\p{L}\d])(?:\s*[×x*]\s*(\d+))?/iu',$raw,$matches,PREG_SET_ORDER);
 foreach($matches as $m){$sku=strtoupper($m[1]);$size=strtr(strtoupper($m[2]),['XXXL'=>'3XL','XXL'=>'2XL']);$key=$sku.'|'.$size;if(preg_match('/(?:\bOK|NHẬN|GIỮ)\s*[:,-]?\s*'.preg_quote($sku,'/').'(?![\p{L}\d])/iu',$raw))continue;$explicit=true;if(!isset($pool[$key]))return ['items'=>[],'error'=>'Mã / size trong thông báo không khớp đơn.'];$qty=isset($m[3])&&$m[3]!==''?(int)$m[3]:null;if($qty===null&&$pool[$key]>1)return ['items'=>[],'error'=>'Cần xác nhận số lượng hoàn của '.$sku.' '.$size.'.'];$qty??=1;if($qty<1||$qty>$pool[$key])return ['items'=>[],'error'=>'Số lượng hoàn vượt số lượng đã gửi.'];$selected[$key]=max($selected[$key]??0,$qty);}
 if($explicit&&$selected)return ['items'=>$selected,'error'=>''];if(count($pool)===1&&reset($pool)===1)return ['items'=>$pool,'error'=>''];return ['items'=>[],'error'=>'Đơn nhiều sản phẩm / số lượng: cần xác nhận hàng thực hoàn.'];
}
function stock_flow_schema(PDO $db):void {$db->exec('CREATE TABLE IF NOT EXISTS stock_return_allocations(tracking TEXT PRIMARY KEY,items TEXT NOT NULL,revision INTEGER NOT NULL,actor TEXT NOT NULL,note TEXT NOT NULL,updated_at TEXT NOT NULL)');}
function stock_flow(PDO $db,array $rows,bool $historicalReport=false):array {
 stock_flow_schema($db);$messages=[];$received=[];$manual=[];$tables=array_column($db->query("SELECT name FROM sqlite_master WHERE type='table'")->fetchAll(),'name');
 if(in_array('return_messages',$tables,true))foreach($db->query('SELECT entries FROM return_messages ORDER BY id') as $m)foreach(json_decode($m['entries'],true)??[] as $e)if(($e['state']??'')==='matched'&&($code=stock_tracking($e['tracking']??''))!=='')$messages[$code]=$e;
 if(in_array('return_receipts',$tables,true))foreach($db->query("SELECT tracking FROM return_receipts WHERE state='matched'") as $e)if(($code=stock_tracking($e['tracking']))!=='')$received[$code]=true;
 foreach($db->query('SELECT * FROM stock_return_allocations') as $m)$manual[$m['tracking']]=$m;
 $shortages=stock_group_rows(array_values(array_filter($rows,'stock_is_shortage')));$active=array_values(array_filter($rows,static fn($r)=>!stock_is_shortage($r)));$cases=[];$outcomes=[];$totals=[];$seen=[];foreach(stock_group_rows($active) as $row){if(!$row['created'])continue;$code=stock_tracking($row['tracking']);$identity=$code!==''?$code:$row['sheetId'].'|'.$row['row'];if(isset($seen[$identity]))continue;$seen[$identity]=true;$out=stock_item_map($row['items']);$entry=$messages[$code]??null;$wasReceived=isset($received[$code])||!empty($row['returned']);if(!$entry&&($wasReceived||board_historical_return_reason($row['status']??'')))$entry=['raw'=>($wasReceived&&!stock_kept_items($out,$row['status']??'')?$row['text'].' ':'').($row['status']??''),'reason'=>$row['status']??''];$result=stock_resolve_outcome($row,$entry,$wasReceived,isset($manual[$code])?json_decode($manual[$code]['items'],true):null);$outcomes[]=['identity'=>$identity,'row'=>$row,'result'=>$result];
 if($result['returnEvent'])$cases[]=['tracking'=>$code,'sheet'=>$row['sheet'],'row'=>$row['row'],'state'=>$result['state'],'order'=>$row['text'],'items'=>$result['items'],'error'=>$result['error'],'revision'=>(int)($manual[$code]['revision']??0),'reason'=>$messages[$code]['reason']??$row['status']??'','note'=>$manual[$code]['note']??''];
 foreach($out as $key=>$qty){$totals[$key]??=['sold'=>0,'shipping'=>0,'returning'=>0,'autoReturned'=>0,'delivered'=>0];$totals[$key]['sold']+=$qty;}
 foreach(['shipping'=>'shipping','delivered'=>'delivered','returning'=>'returning','received'=>'autoReturned'] as $field=>$metric)foreach($result[$field] as $key=>$qty){$totals[$key]??=['sold'=>0,'shipping'=>0,'returning'=>0,'autoReturned'=>0,'delivered'=>0];$totals[$key][$metric]+=$qty;}
 }
 foreach($shortages as $row)foreach(stock_item_map($row['items']) as $key=>$qty){$totals[$key]??=['sold'=>0,'shipping'=>0,'returning'=>0,'autoReturned'=>0,'delivered'=>0];$totals[$key]['outOfStock']=($totals[$key]['outOfStock']??0)+$qty;}
 return ['totals'=>$totals,'cases'=>$cases,'shortages'=>$shortages,'outcomes'=>$outcomes];
}
function stock_return_save(PDO $db,array $input,array $user):array {
 team_require_owner();stock_flow_schema($db);$code=stock_tracking((string)($input['tracking']??''));$text=trim((string)($input['items']??''));$note=trim((string)($input['note']??''));if($code===''||strlen($text)>2000||mb_strlen($note)>1000)throw new RuntimeException('Kiểm tra mã vận đơn / sản phẩm.',400);$db->exec('BEGIN IMMEDIATE');try{$catalog=board_catalog($db);$board=board_rows($db,$catalog);$flow=stock_flow($db,$board['rows']);$case=null;foreach($flow['cases'] as $c)if($c['tracking']===$code)$case=$c;if(!$case)throw new RuntimeException('Đơn chưa có thông báo hoàn hoặc file nhận hoàn khớp mã.',400);if($case['revision']!==(int)($input['revision']??0))throw new RuntimeException('Phân bổ vừa được sửa. Làm mới trước khi tiếp tục.',409);$items=[];if($text!=='0'){$p=board_lines($text,$catalog);if($p['errors']||!$p['items'])throw new RuntimeException('Nhập dạng E1 S × 1 + E2 M × 2; nhập 0 nếu không có hàng hoàn.',400);$items=stock_item_map($p['items']);}foreach(stock_group_rows(array_values(array_filter($board['rows'],static fn($r)=>!stock_is_shortage($r)))) as $row)if(stock_tracking($row['tracking'])===$code){$valid=stock_return_items($row,null,$items);if($valid['error'])throw new RuntimeException($valid['error'],400);break;}$q=$db->prepare('SELECT * FROM stock_return_allocations WHERE tracking=?');$q->execute([$code]);$before=$q->fetch();$db->prepare('INSERT INTO stock_return_allocations VALUES(?,?,1,?,?,?) ON CONFLICT(tracking) DO UPDATE SET items=excluded.items,revision=revision+1,actor=excluded.actor,note=excluded.note,updated_at=excluded.updated_at')->execute([$code,json_encode($items),$user['username'],$note,gmdate('c')]);people_audit('stock_return_allocation',$code,['before'=>$before,'items'=>$items,'note'=>$note],$db);$db->exec('COMMIT');return ['ok'=>true];}catch(Throwable $e){$db->exec('ROLLBACK');throw $e;}
}
